tape( 'the function throws an error if provided an options argument which is not an object', function test( t ) {
	var values;
	var x;
	var i;

	x = zeros( [ 4 ], {
		'dtype': 'float64'
	});

	values = [
		'5',
		true,
		false,
		null,
		void 0,
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			rfftf( x, value );
		};
	}
});

tape( 'the function computes the FFT of a real-valued input (float64, row-major)', function test( t ) {
	var expected;
	var view;
	var xbuf;
	var out;
	var x;

	xbuf = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	x = new ndarray( 'float64', xbuf, [ 4 ], [ 1 ], 0, 'row-major' );
	out = rfftf( x );
	view = reinterpret128( getData( out ), 0 );

	t.strictEqual( getDType( out ), 'complex128', 'returns expected value' );
	t.deepEqual( getShape( out ), [ 3 ], 'returns expected value' );

	// Expected: (10+0i), (-2+2i), (-2+0i):
	expected = new Float64Array( [ 10.0, 0.0, -2.0, 2.0, -2.0, 0.0 ] );
	t.deepEqual( view, expected, 'returns expected value' );

	t.end();
});

